import {withParticle} from './korean.js';
export const MAIN_ENDINGS=['true','postdoc','institute','corporate','unrelated','startup','unemployed','youtuber','resident_researcher'];
export function endingCollection(gallery){const seen=new Set(gallery.map(e=>e.ending));const count=MAIN_ENDINGS.filter(id=>seen.has(id)).length;return {count,total:MAIN_ENDINGS.length,unlocked:count>=5,complete:count===MAIN_ENDINGS.length};}
export function keepGallery(entries){const first=new Map();for(const e of entries)if(!first.has(e.ending))first.set(e.ending,e);const retained=entries.slice(0,40);for(const e of first.values())if(!retained.some(r=>r.id===e.id)){const index=retained.findLastIndex(r=>first.get(r.ending)?.id!==r.id);if(index>=0)retained.splice(index,1,e);}return retained;}
export function retirementScenes(gallery){if(!endingCollection(gallery).unlocked)return [];const get=id=>gallery.find(e=>e.ending===id)?.name;const scenes=['퇴임식 날, 강당의 조명이 켜졌다. 여러 회차에서 함께한 제자들의 이야기가 한 자리에서 만난다. 서로 다른 삶을 하나의 서열로 나누지 않는 회상이다.'];if(get('true'))scenes.push(`${get('true')} 교수는 앞줄에서 축사를 준비하고 있었다. “질문을 끝까지 살피는 법을 배웠습니다.” 이번에는 지도교수가 객석에서 듣는다.`);if(get('postdoc'))scenes.push(`${get('postdoc')} 박사가 해외에서 들어와 앉았다. 이번에는 일주일 전에 연락했다. 다음 연구의 이야기는 식이 끝난 뒤 천천히 나누기로 했다.`);for(const id of ['institute','corporate','startup','resident_researcher','unemployed'])if(get(id))scenes.push(`${get(id)}도 자리에 왔다. 각자의 일과 생활 속에서 가져온 안부를 나누었다. 지금 어디에서 일하는지보다 오늘 함께 만났다는 사실이 먼저였다.`);if(get('youtuber'))scenes.push(`${get('youtuber')} 박사는 촬영 안내를 확인하고 카메라를 내려놓았다. 오늘은 영상보다 서로의 이야기를 듣는 시간을 남기기로 했다.`);if(get('unrelated'))scenes.push(`맨 뒷줄 빈자리에는 ${withParticle(get('unrelated'),'이/가')} 공개를 허락한 산 사진 엽서가 놓였다. “건강하세요.” 더 긴 연락을 요구하지는 않았다.`);scenes.push('마지막 인사에서 교수는 연구실의 오래된 기계를 이야기했다. 그 곁에서 함께 실패를 정리하고 다시 질문했던 시간을. 오래된 장비는 연구실에 남지만, 배움은 각자의 삶으로 이어졌다.');if(endingCollection(gallery).complete)scenes.push('모든 주요 후일담을 모은 기록의 마지막 장. 강당이 비어 가고, 연구실 문을 천천히 닫는다. 다음 질문을 이어 갈 사람들에게 자리를 남긴다.');return scenes;}
